module.exports = {"schema":1,"revision":296,"topic_id":72,"topic_number":46,"pdf_source_name":"TEMA_61_RESCATE_EN_ACCIDENTES_DE_TRAFICO.pdf","original_images":5,"legacy_inactive_graphics":32,"pdf_sha256":"a477de3df3f263c3f95ca2c20d0c4b3a43f618f0cef1dc6df4448d5ec29c2bff","pdf_page_count":126,"questions":[{"id":2863,"manual_page":"346","stem":"En la estabilización de un turismo eléctrico se dispone de bloques escalonados y de cuñas pequeñas. ¿Qué criterio conjunto evita comprometer el apoyo y respeta la preferencia del manual?","options":["Excluir solo los bajos del motor y preferir el bloque invertido a una cuña pequeña de calce.","Permitir el apoyo en las zonas identificadas para batería y preferir la cuña pequeña al bloque invertido.","Excluir las zonas indicadas como no aptas para apoyo y preferir una cuña pequeña al bloque invertido.","Excluir las zonas de apoyo permitidas y utilizar preferentemente el bloque escalonado invertido."],"correct_index":2,"explanation":"La imagen 144 distingue las zonas a evitar en eléctricos; el texto de la misma página admite el bloque invertido como cuña, pero prefiere una cuña pequeña.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 346. La imagen 144 distingue las zonas a evitar en eléctricos; el texto de la misma página admite el bloque invertido como cuña, pero prefiere una cuña pequeña.","old_stem_md5":"78140616ac630e9112463b9499a0241e","coverage_id":302360,"source_page":70,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2864,"manual_page":"346","stem":"El material de estabilización incluye un bloque escalonado, una cuña pequeña y un separador. Si únicamente se desea completar el calce sin elevar el turismo, ¿qué elección reproduce la preferencia del CEIS?","options":["Invertir preferentemente el bloque escalonado; la cuña pequeña se reserva para elevar el vehículo.","Utilizar preferentemente la cuña pequeña; el bloque invertido puede actuar también como cuña.","Descartar el bloque invertido y la cuña pequeña; el calce solo puede realizarse con puntales.","Emplear primero el separador como calzo; invertir el bloque escalonado solo después de elevarlo."],"correct_index":1,"explanation":"El manual reconoce la utilidad del bloque escalonado invertido para calzar, aunque recomienda preferentemente una cuña pequeña.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 346. El manual reconoce la utilidad del bloque escalonado invertido para calzar, aunque recomienda preferentemente una cuña pequeña.","old_stem_md5":"12d8cb47b3873c6c068fd69d2f284f39","coverage_id":302420,"source_page":70,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2865,"manual_page":"347","stem":"En un turismo volcado sobre un costado deben colocarse apoyos antes de crear una abertura lateral. ¿Qué combinación explica la inestabilidad y condiciona su emplazamiento?","options":["Apoyo en el lado más estrecho y centro de gravedad elevado; ampliar la base sin invadir futuros cortes.","Apoyo en el lado más ancho y centro de gravedad elevado; retirar puntales durante cada corte.","Apoyo en el lado más ancho y centro de gravedad bajo; concentrar los apoyos junto a los cortes previstos.","Apoyo en el lado más estrecho y centro de gravedad bajo; reducir la base para facilitar el acceso."],"correct_index":0,"explanation":"En posición lateral, el coche apoya sobre su lado más estrecho y eleva su centro de gravedad. El CEIS pide aumentar la base y prever las zonas de corte.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 347. En posición lateral, el coche apoya sobre su lado más estrecho y eleva su centro de gravedad. El CEIS pide aumentar la base y prever las zonas de corte.","old_stem_md5":"0b66f4e08747098404e7251a492fdf60","coverage_id":302445,"source_page":71,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2866,"manual_page":"347","stem":"Se estabiliza un vehículo apoyado sobre un costado mediante puntales mecánicos sobre terreno de apoyo. ¿Qué medidas complementarias recoge el manual para impedir su deslizamiento?","options":["Apoyar las bases directamente sin calces y sujetar los puntales únicamente entre sí, no al vehículo.","Calzar los extremos superiores, dejar libres las bases y retirar las correas tras el primer tensado.","Aumentar solo la presión ascendente, prescindiendo de cuñas si los puntales tienen apoyo metálico.","Calzar las bases, asegurar los puntales al vehículo y considerar el arriostramiento cuando sea posible."],"correct_index":3,"explanation":"El CEIS exige cuñas bajo las bases de puntales mecánicos y aconseja sujeción con correas o sistemas unidos al vehículo y arriostramiento cuando sea posible.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 347. El CEIS exige cuñas bajo las bases de puntales mecánicos y aconseja sujeción con correas o sistemas unidos al vehículo y arriostramiento cuando sea posible.","old_stem_md5":"039b5111748968ab43975236f850910a","coverage_id":302468,"source_page":71,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2867,"manual_page":"364","stem":"En la creación de una tercera puerta, el corte inferior del montante B resulta difícil de aprovechar con las puntas del separador. ¿Qué geometría y finalidad concreta contempla el procedimiento?","options":["Practicar un alivio transversal en el pilar C para facilitar la instalación del cilindro de rescate.","Practicar un alivio longitudinal en el pilar A para facilitar la retirada posterior de la aleta.","Practicar un alivio en forma de quesito para facilitar la introducción posterior de las puntas.","Practicar un alivio en forma de quesito sobre el techo para reducir la longitud del montante A."],"correct_index":2,"explanation":"La página 364 sitúa el corte de alivio inferior en el pilar B; hacerlo en forma de quesito facilita introducir después las puntas del separador.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 364. La página 364 sitúa el corte de alivio inferior en el pilar B; hacerlo en forma de quesito facilita introducir después las puntas del separador.","old_stem_md5":"e46d11fb40e44931bbf453091ccbddb2","coverage_id":302469,"source_page":88,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2868,"manual_page":"364","stem":"Para formar una tercera puerta se ha realizado ya el alivio inferior de un montante B. ¿Qué actuación se corresponde con el siguiente corte de ese montante, antes de completar su retirada?","options":["Practicar un corte en la base del pilar A y continuar el abatimiento del salpicadero.","Practicar un corte en la parte superior del mismo pilar B y continuar la apertura lateral.","Practicar el corte superior del pilar C, dejando intacta la parte alta del montante B.","Practicar un corte en la zona baja del guardabarros y continuar con el pilar delantero."],"correct_index":1,"explanation":"En el procedimiento de tercera puerta, la imagen 221 identifica el corte superior del pilar B, tras el alivio inferior de la imagen 220.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 364. En el procedimiento de tercera puerta, la imagen 221 identifica el corte superior del pilar B, tras el alivio inferior de la imagen 220.","old_stem_md5":"e0f04c31cc2f0b9c7ca7282bcb75be13","coverage_id":302470,"source_page":88,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2869,"manual_page":"364","stem":"Se ha liberado el montante B en una maniobra destinada a crear una tercera puerta y el panel lateral requiere un alivio adicional. ¿Qué elemento recibe ese corte según la secuencia representada?","options":["El montante C, para completar la modificación del costado y permitir la apertura buscada.","La parte inferior del marco del parabrisas, para completar el apoyo del cilindro de separación.","El refuerzo del guardabarros, para completar la maniobra de empuje sobre el salpicadero.","El montante A, para completar el abatimiento del salpicadero y liberar el volante."],"correct_index":0,"explanation":"La imagen 223 del manual corresponde al corte de alivio del pilar C en la creación de una tercera puerta.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 364. La imagen 223 del manual corresponde al corte de alivio del pilar C en la creación de una tercera puerta.","old_stem_md5":"812ba67db1ed86fb659165482c9d04a7","coverage_id":302475,"source_page":88,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2870,"manual_page":"375","stem":"En el abatimiento de salpicadero mediante cilindro de rescate, la proximidad de la víctima limita el espacio de trabajo. ¿Qué alivio y posible momento de ejecución contempla el CEIS?","options":["Corte en el techo sobre el pilar A, que sustituye cualquier alivio en su parte inferior.","Corte en la parte alta del pilar C, que se realiza antes de desmontar el guardabarros.","Corte en la base del pilar A, que puede hacerse antes de colocar el cilindro cuando falta espacio.","Corte en la base del pilar B, que solo debe hacerse una vez retirado el cilindro ya extendido."],"correct_index":2,"explanation":"El CEIS indica corte de descarga en la parte inferior del pilar A y permite anticiparlo a la colocación del cilindro si el espacio es reducido.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 375. El CEIS indica corte de descarga en la parte inferior del pilar A y permite anticiparlo a la colocación del cilindro si el espacio es reducido.","old_stem_md5":"833bd5a136f77b2e660af7fe248080e0","coverage_id":302486,"source_page":99,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2871,"manual_page":"375","stem":"Tras realizar el alivio inferior del pilar A, el salpicadero ofrece resistencia al avance del cilindro. ¿Qué maniobra complementaria cita el manual para facilitar el desplazamiento?","options":["Retirar el montante C y efectuar después un corte de descarga en el marco del techo.","Mantener la aleta y efectuar después un corte de descarga únicamente en el pilar B.","Retirar la aleta y efectuar después un corte de descarga en la zona del guardabarros.","Mantener el guardabarros sin cortes y efectuar después el alivio inferior del pilar C."],"correct_index":2,"explanation":"El procedimiento admite retirar la aleta y practicar un corte complementario en el guardabarros para favorecer el movimiento del salpicadero.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 375. El procedimiento admite retirar la aleta y practicar un corte complementario en el guardabarros para favorecer el movimiento del salpicadero.","old_stem_md5":"c2500ece7eaa4c76dad2aea2873bbade","coverage_id":302498,"source_page":99,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2872,"manual_page":"383","stem":"Un camión volcado tiene la escotilla del techo cerrada, de accionamiento eléctrico, y se ha interrumpido la alimentación. ¿Qué posibilidad de acceso distingue el CEIS respecto de una escotilla ya abierta?","options":["La cerrada exige abrirla por otros medios o crear una abertura; la ya abierta permite el paso.","La cerrada permite paso directo sin intervención; la ya abierta requiere una abertura adicional.","La cerrada y la abierta requieren necesariamente cortar el techo antes de acceder al habitáculo.","La cerrada conserva el accionamiento eléctrico; la ya abierta exige desmontar el marco."],"correct_index":0,"explanation":"Sin alimentación no se puede operar eléctricamente la escotilla; si está cerrada habrá que eliminarla o abrir el cristal o chapa; si estaba abierta puede utilizarse.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 383. Sin alimentación no se puede operar eléctricamente la escotilla; si está cerrada habrá que eliminarla o abrir el cristal o chapa; si estaba abierta puede utilizarse.","old_stem_md5":"df4ec89f633cca37cc94d83641c03a90","coverage_id":302576,"source_page":107,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2873,"manual_page":"383","stem":"En la primera aproximación a la cabina alta de un camión se prevé usar una escalera y valorar las puertas. ¿Qué combinación de comprobaciones previas establece el manual?","options":["Retirar cristales de la calzada antes de apoyar la escalera y probar puertas a mano o con palanqueta antes de hidráulica pesada.","Evitar siempre la escalera si hay cristales y usar hidráulica pesada antes de cualquier intento con palanqueta.","Retirar cristales solo después de colocar la escalera y desmontar las bisagras antes de probar la apertura manual.","Apoyar la escalera sobre los cristales para inmovilizarla y usar primero hidráulica pesada en las puertas."],"correct_index":0,"explanation":"El CEIS exige retirar cristales antes de apoyar la escalera y probar la apertura de puertas a mano o con palanqueta antes de utilizar herramienta hidráulica pesada.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 383. El CEIS exige retirar cristales antes de apoyar la escalera y probar la apertura de puertas a mano o con palanqueta antes de utilizar herramienta hidráulica pesada.","old_stem_md5":"443740442046d9876b2846c651bc5048","coverage_id":302591,"source_page":107,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2874,"manual_page":"386","stem":"Antes de abrir el umbral de una cabina elevada se dispone de separador y cizalla. ¿Qué preparación y configuración posterior describe el CEIS para favorecer su apertura?","options":["Practicar primero un corte del techo y reservar el aplastamiento del umbral para la liberación final.","Aplastar primero el umbral con separador y ejecutar después los cortes de alivio que permitan abrirlo.","Realizar primero el corte alto del pilar C y aplastar después el umbral con el cilindro extendido.","Aplastar primero el montante B con la cizalla y eliminar después el umbral mediante tracción del techo."],"correct_index":1,"explanation":"En la página 386 se recomienda aplastar el umbral con el separador antes de practicar los cortes que permiten su apertura.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 386. En la página 386 se recomienda aplastar el umbral con el separador antes de practicar los cortes que permiten su apertura.","old_stem_md5":"d9a623eb4c0e26543bde3bfdc79d9395","coverage_id":302612,"source_page":110,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2875,"manual_page":"386","stem":"Una vez practicados los cortes de descarga del montante A y del umbral de la cabina, se prepara el empuje del frontal. ¿Dónde se coloca el cilindro y qué zona sirve de referencia de altura?","options":["Entre los montantes A y B, tomando como referencia la parte inferior del estribo.","Entre los montantes A y B, tomando como referencia la altura de la cerradura de la puerta.","Entre los montantes A y C, tomando como referencia el borde superior del parabrisas.","Entre los montantes B y C, tomando como referencia la parte inferior de la ventanilla."],"correct_index":1,"explanation":"Tras aliviar el pilar A y el umbral, se sitúa el cilindro entre A y B a la altura de la cerradura de la puerta.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 386. Tras aliviar el pilar A y el umbral, se sitúa el cilindro entre A y B a la altura de la cerradura de la puerta.","old_stem_md5":"d5ef8407892de5c6cd97d26120ebafa7","coverage_id":302623,"source_page":110,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2876,"manual_page":"386","stem":"En el desplazamiento del frontal de un camión el primer cilindro llega a su límite y es necesario instalar otro de mayor longitud. ¿Qué disposición relativa se describe para continuar el empuje?","options":["Instalar el segundo cilindro por debajo del primero, descargando el apoyo sobre el umbral sin calces.","Instalar el segundo cilindro a la misma altura del primero, pero sobre el lado opuesto del volante.","Instalar el segundo cilindro por encima del primero, con apoyos seguros para impedir su deslizamiento.","Instalar el segundo cilindro en el pilar C, sin necesidad de mantener apoyo sobre el marco delantero."],"correct_index":2,"explanation":"La página 386 dispone el cilindro de mayor tamaño por encima del primero y exige apoyarlo de modo que no deslice.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 386. La página 386 dispone el cilindro de mayor tamaño por encima del primero y exige apoyarlo de modo que no deslice.","old_stem_md5":"985d09b87b716eaaf21cfb0cf79c140a","coverage_id":302634,"source_page":110,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2877,"manual_page":"284","stem":"Durante una colisión frontal con barrera rígida, la sección delantera acaba de detenerse, pero la central y la trasera mantienen su avance por inercia. ¿Qué deformación identifica el paso siguiente de la secuencia?","options":["La sección trasera se inmoviliza antes que la central; el pilar delantero se desplaza hacia el frente.","El pilar delantero se pliega en su extremo superior sin alterar las puertas ni el perfil lateral del techo.","El pilar delantero se desplaza hacia atrás y gira sobre su base; el techo y la luna posterior se desalinean.","El pilar delantero gira sobre su parte alta; la zona central ya permanece inmóvil y el techo no se deforma."],"correct_index":2,"explanation":"El paso tercero de la colisión frontal describe la detención de la sección delantera, el avance del resto y el giro inferior del pilar con alteración del techo y las puertas.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 284. El paso tercero de la colisión frontal describe la detención de la sección delantera, el avance del resto y el giro inferior del pilar con alteración del techo y las puertas.","old_stem_md5":"464f6b5ae5ff2350d3e37ee25757dfae","coverage_id":302648,"source_page":8,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2878,"manual_page":"290","stem":"En la tabla comparativa entre carrocería autoportante y chasis independiente se consideran peso, rigidez, ruido y corrosión. ¿Cuál de las siguientes asociaciones respeta las ventajas e inconvenientes indicados?","options":["Menor peso para iguales prestaciones y mayor rigidez con el mismo peso; más ruido de transmisión y corrosión más temprana.","Mayor peso para iguales prestaciones y menor rigidez con el mismo peso; menos ruido de transmisión y corrosión más temprana.","Menor peso para iguales prestaciones y menor rigidez con el mismo peso; menos ruido de transmisión y corrosión más tardía.","Mayor peso para iguales prestaciones y mayor rigidez con el mismo peso; más ruido de transmisión y corrosión más tardía."],"correct_index":0,"explanation":"La tabla 4 atribuye a la autoportante menor peso y mayor rigidez como ventajas; incremento del ruido de transmisión y deterioro por corrosión más temprano como inconvenientes.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 290. La tabla 4 atribuye a la autoportante menor peso y mayor rigidez como ventajas; incremento del ruido de transmisión y deterioro por corrosión más temprano como inconvenientes.","old_stem_md5":"5ce97497f51b877103a77b500bc91b6d","coverage_id":302656,"source_page":14,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2879,"manual_page":"323","stem":"En un accidente con posibles ocupantes despedidos se organiza simultáneamente el triaje, la búsqueda exterior y la recuperación de la circulación. ¿Qué asignación respeta el reparto funcional del CEIS?","options":["Sanitarios: búsqueda de despedidos; bomberos: restablecimiento de circulación; fuerzas del orden: triaje.","Sanitarios: restablecimiento de circulación; bomberos: triaje; fuerzas del orden: búsqueda de despedidos.","Sanitarios: triaje; bomberos: restablecimiento de circulación; fuerzas del orden: búsqueda de despedidos.","Sanitarios: triaje; bomberos: búsqueda de posibles despedidos; fuerzas del orden: restablecimiento de circulación."],"correct_index":3,"explanation":"La tabla 5 atribuye el triaje y las prioridades a sanitarios, la localización de posibles despedidos a bomberos y la circulación a las fuerzas del orden.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 323. La tabla 5 atribuye el triaje y las prioridades a sanitarios, la localización de posibles despedidos a bomberos y la circulación a las fuerzas del orden.","old_stem_md5":"2ebff842dd1fc6501f155a84d6f7e261","coverage_id":302664,"source_page":47,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2880,"manual_page":"328","stem":"Un mando revisa la secuencia general de intervención y pretende anticipar la estabilización antes de efectuar la valoración inicial. ¿Qué relación entre reconocimiento y estabilización se corresponde con el procedimiento del CEIS?","options":["El reconocimiento se limita a los vehículos de apoyo; la estabilización posterior determina las víctimas despedidas.","El reconocimiento examina heridos, vehículo y entorno; la estabilización posterior afecta al vehículo y a los heridos.","El reconocimiento examina únicamente a los heridos; la estabilización posterior asume todo el análisis del entorno.","El reconocimiento fija el vehículo en su posición; la estabilización posterior examina heridos y entorno."],"correct_index":1,"explanation":"La imagen 100 organiza el reconocimiento de heridos y de vehículo/entorno antes de la estabilización del vehículo y de los heridos.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 328. La imagen 100 organiza el reconocimiento de heridos y de vehículo/entorno antes de la estabilización del vehículo y de los heridos.","old_stem_md5":"376927dd4577e8351c125257f21abf2e","coverage_id":302670,"source_page":52,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2881,"manual_page":"329","stem":"En el mismo servicio se señalizan dos siniestros, uno en doble sentido y otro en un solo sentido, conforme a las distancias del manual. ¿Qué reparto mínimo y visibilidad se deducen?","options":["Doble sentido: 50 m solo antes; único sentido: 50 m antes y después; balizas desde 100 m.","Doble sentido: 50 m antes y después; único sentido: 50 m por detrás del accidente; balizas desde 100 m.","Doble sentido: 50 m antes y después; único sentido: 100 m después del accidente; balizas desde 50 m.","Doble sentido: 100 m antes y después; único sentido: 50 m después del accidente; balizas desde 50 m."],"correct_index":1,"explanation":"El CEIS cita mínimo de 50 m por delante y detrás en doble sentido, 50 m por detrás en único sentido, y balizas visibles desde al menos 100 m.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 329. El CEIS cita mínimo de 50 m por delante y detrás en doble sentido, 50 m por detrás en único sentido, y balizas visibles desde al menos 100 m.","old_stem_md5":"a9b4fba6c506329cafc527b8d24896d6","coverage_id":302733,"source_page":53,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2882,"manual_page":"340","stem":"En un vehículo industrial híbrido, el desconectador delantero de la batería HV está accionado, pero el motor de combustión sigue funcionando. Según el CEIS, ¿qué condición falta para alcanzar el estado descrito como ausencia de tensión HV?","options":["Detener también el motor de combustión interna, además de mantener accionada la desconexión HV.","Mantener en marcha el motor térmico y abrir únicamente los bornes de las baterías de 12 V.","Mantener el motor de combustión al ralentí y desconectar exclusivamente las luces de servicio.","Accionar de nuevo el mismo desconectador HV sin alterar el funcionamiento del motor de combustión."],"correct_index":0,"explanation":"La página 340 indica expresamente que el desconectador HV delantero no basta si el motor térmico sigue en funcionamiento; también debe pararse.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 340. La página 340 indica expresamente que el desconectador HV delantero no basta si el motor térmico sigue en funcionamiento; también debe pararse.","old_stem_md5":"dfe7af665c6291ba63c79e728a50fa4d","coverage_id":302745,"source_page":64,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2883,"manual_page":"351","stem":"Un autobús vuelca sobre un turismo y los equipos necesitan impedir el movimiento relativo antes de acceder a ambos habitáculos. ¿Qué secuencia de estabilización y unión recoge el manual?","options":["Unir inicialmente ambos vehículos por las ventanas enfrentadas y estabilizar después solo el autobús.","Estabilizar inicialmente el autobús por separado y retirar todos los apoyos del turismo antes de unirlos.","Elevar inicialmente el autobús por su techo y estabilizar después el turismo sin conexiones entre ellos.","Estabilizar inicialmente cada vehículo y unirlos después con correas, cuñas u otros medios como un solo bloque."],"correct_index":3,"explanation":"La página 351 prescribe estabilización independiente previa y posterior unión solidaria, con correas y cuñas entre vehículos.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 351. La página 351 prescribe estabilización independiente previa y posterior unión solidaria, con correas y cuñas entre vehículos.","old_stem_md5":"2c1aaac2d89a7fecb0b6d9c1780b374d","coverage_id":302833,"source_page":75,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2884,"manual_page":"357","stem":"Para retirar una ventanilla templada intacta junto a una víctima, ¿qué secuencia y efecto sobre los fragmentos reproduce la técnica del CEIS?","options":["Proteger al ocupante, cortar el vidrio laminado por el centro y retirar la lámina adhesiva sin granetear.","Proteger al ocupante, adherir una lámina al vidrio y granetear una esquina para retener gran parte de los fragmentos.","Proteger al ocupante, adherir una lámina al parabrisas y practicar un alivio en el pilar B para liberar el vidrio.","Proteger al ocupante, granetear el centro y adherir una lámina después de fragmentar el vidrio."],"correct_index":1,"explanation":"El CEIS exige protección previa del ocupante, lámina o cinta en los vidrios templados y granetazo en una esquina; los fragmentos quedan principalmente adheridos.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 357. El CEIS exige protección previa del ocupante, lámina o cinta en los vidrios templados y granetazo en una esquina; los fragmentos quedan principalmente adheridos.","old_stem_md5":"0f1f643dbbabe913a845dc562f27c777","coverage_id":302843,"source_page":81,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2885,"manual_page":"362","stem":"Durante la apertura de una puerta de ala de gaviota se han cortado sus montantes anterior y posterior. ¿Qué movimiento posterior y qué elemento lo provoca según el manual?","options":["La parte superior gira hacia arriba impulsada por los muelles de presión de gas.","La parte superior gira hacia abajo impulsada por los muelles de presión de gas.","El panel superior se desplaza horizontalmente mediante el motor de cierre centralizado.","El panel inferior gira hacia arriba por la tensión acumulada en las bisagras."],"correct_index":0,"explanation":"Tras cortar los montantes delantero y trasero, la parte superior de la puerta gira hacia arriba por la acción de los muelles de presión de gas.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 362. Tras cortar los montantes delantero y trasero, la parte superior de la puerta gira hacia arriba por la acción de los muelles de presión de gas.","old_stem_md5":"69d9bfe79addf7b788132deba18495f7","coverage_id":302877,"source_page":86,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2886,"manual_page":"370","stem":"Antes del corte de montantes B y C para retirar el techo, se inspeccionan los sistemas de airbag de ventana. ¿Qué localización y precaución son las que recoge el CEIS?","options":["Buscar el generador bajo C en el estribo y evitar dañarlo; ejecutar el corte de B sobre la cerradura.","Buscar el generador en el guardabarros delantero y evitar dañarlo; cortar C por su parte más baja.","Buscar el generador sobre A en el salpicadero y evitar dañarlo; cortar B a la altura del reposacabezas.","Buscar el generador sobre B en el marco del techo y evitar dañarlo; ejecutar el corte de C lo más alto posible."],"correct_index":3,"explanation":"El manual advierte del generador en el marco del techo sobre B y describe el corte alto de C sin dañar los sistemas de seguridad.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 370. El manual advierte del generador en el marco del techo sobre B y describe el corte alto de C sin dañar los sistemas de seguridad.","old_stem_md5":"48aaf8ce73e2994f0ebd619d66e9a877","coverage_id":302887,"source_page":94,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2887,"manual_page":"374","stem":"Un cilindro eleva el vehículo mientras unos puntales estabilizan el espacio creado. ¿Qué distribución de esfuerzos preserva la estabilidad que exige el CEIS?","options":["El cilindro deja de actuar y los puntales aplican una carga ascendente adicional para fijarlo.","El cilindro realiza la elevación y los puntales la refuerzan empujando también hacia arriba.","El cilindro realiza la elevación y los puntales sostienen el vehículo, sin presionar hacia arriba.","Los puntales realizan la elevación y el cilindro únicamente bloquea los desplazamientos laterales."],"correct_index":2,"explanation":"El CEIS advierte que los puntales solo soportan: si empujan hacia arriba podrían desplazar el cilindro de separación.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 374. El CEIS advierte que los puntales solo soportan: si empujan hacia arriba podrían desplazar el cilindro de separación.","old_stem_md5":"1a412525f997152fcd4cccc3c16c2a89","coverage_id":302906,"source_page":98,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":2888,"manual_page":"384","stem":"Se retira con un separador la puerta de un camión y ya se ha conseguido introducir la herramienta entre la puerta y el montante A. ¿Qué avance y precaución concreta siguen?","options":["Desplazar el separador hacia el techo, actuar sobre el montante B y retirar la puerta sin sujeción.","Desplazar el separador hacia el estribo, actuar sobre el pilar C y dejar la puerta libre al romper los goznes.","Desplazar el separador hacia la cerradura, actuar allí nuevamente y soltar la puerta antes de asegurarla.","Desplazar el separador hacia las bisagras, actuar allí nuevamente y asegurar la puerta para impedir su caída."],"correct_index":3,"explanation":"En la página 384 el separador avanza desde el espacio puerta–montante A hacia las bisagras; la puerta se asegura desde el lado opuesto con cuerda o correas.","question_family":"CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 384. En la página 384 el separador avanza desde el espacio puerta–montante A hacia las bisagras; la puerta se asegura desde el lado opuesto con cuerda o correas.","old_stem_md5":"3d019dc32f871671d66658d1562d9cf4","coverage_id":302930,"source_page":108,"old_family":"CORRECTA","old_validation_version":7,"kind":"texto"},{"id":3144,"manual_page":"330","stem":"El gráfico reúne la distribución en círculos de trabajo y el emplazamiento de vehículos de protección. Si el radio de la zona caliente se fija en 4 m, ¿qué organización adicional coincide con las cotas y ubicaciones dibujadas?","options":["Zona templada hasta 5–10 m; herramientas en círculo caliente; bomba paralela y a unos 6–10 m del accidente.","Zona templada hasta 3–5 m; herramientas fuera del sector; bomba defensiva oblicua a unos 6–10 m del accidente.","Zona templada hasta 5–10 m; herramientas en el límite interior; bomba defensiva oblicua a unos 6–10 m del accidente.","Zona templada hasta 5–10 m; fragmentos en lona limpia; bomba defensiva a 15 m exactos del accidente."],"correct_index":2,"explanation":"Las imágenes 103 y 105 distinguen círculo caliente de 3–5 m, templada de 5–10 m, zona limpia de herramientas junto al límite interior y bomba defensiva oblicua.","question_family":"GRAFICA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 330. Las imágenes 103 y 105 distinguen círculo caliente de 3–5 m, templada de 5–10 m, zona limpia de herramientas junto al límite interior y bomba defensiva oblicua.","old_stem_md5":"8c889451dc47f0ac2dd2e02cb0f6ebf9","coverage_id":301137,"source_page":54,"old_family":"GRAFICA","old_validation_version":8,"kind":"grafica","externalKey":"T46-GRAF-01"},{"id":3145,"manual_page":"331","stem":"En la vía de tres carriles de sentido único dibujada, dos vehículos de protección se sitúan a ambos lados del siniestro y se mantienen las dos cotas de 15 m. ¿Qué lectura conjunta respeta la figura?","options":["BUP antes y FSV después del accidente; 15 m entre los puntos de referencia de ambos vehículos.","BUP después y FSV antes del accidente; 30 m entre los puntos de referencia de ambos vehículos.","BUP antes y FSV después del accidente; 30 m entre los puntos de referencia de ambos vehículos.","BUP después y FSV antes del accidente; 15 m entre los puntos de referencia de ambos vehículos."],"correct_index":2,"explanation":"La imagen 107 muestra BUP aguas arriba, FSV aguas abajo, y dos tramos de 15 m a cada lado; la suma entre referencias es 30 m.","question_family":"GRAFICA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 331. La imagen 107 muestra BUP aguas arriba, FSV aguas abajo, y dos tramos de 15 m a cada lado; la suma entre referencias es 30 m.","old_stem_md5":"17ce778c20ad9ba035917270a171bc46","coverage_id":301139,"source_page":55,"old_family":"GRAFICA","old_validation_version":8,"kind":"grafica","externalKey":"T46-GRAF-02"},{"id":3146,"manual_page":"337","stem":"La fotografía identifica los terminales de una caja de baterías de vehículo pesado. Si se emplean dos acumuladores de 12 V conectados como indica el CEIS, ¿qué relación simultánea de polaridad y tensión corresponde?","options":["Borne 1 positivo y borne 2 negativo; dos elementos de 12 V conectados en serie proporcionan 24 V.","Borne 1 negativo y borne 2 positivo; dos elementos de 12 V conectados en serie proporcionan 24 V.","Borne 1 negativo y borne 2 positivo; dos elementos de 12 V conectados en paralelo proporcionan 12 V.","Borne 1 positivo y borne 2 negativo; dos elementos de 12 V conectados en paralelo proporcionan 24 V."],"correct_index":0,"explanation":"La imagen 122 identifica 1 como positivo y 2 como negativo; la página 337 establece conexión en serie de dos baterías de 12 V para obtener 24 V.","question_family":"GRAFICA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 337. La imagen 122 identifica 1 como positivo y 2 como negativo; la página 337 establece conexión en serie de dos baterías de 12 V para obtener 24 V.","old_stem_md5":"1287fe28a8097cbfd6aebf0f968e2e7c","coverage_id":301505,"source_page":61,"old_family":"GRAFICA","old_validation_version":8,"kind":"grafica","externalKey":"T46-GRAF-03"},{"id":3147,"manual_page":"337","stem":"En el croquis aparecen dos baterías iguales de 12 V y 100 Ah, unidas mediante el puente 2–3. Despreciando pérdidas, ¿qué magnitudes nominales presenta el conjunto entre 1 y 4, y qué lectura corresponde al puente 2–3?","options":["12 V y 100 Ah entre 1 y 4; aproximadamente 24 V entre 2 y 3.","24 V y 100 Ah entre 1 y 4; aproximadamente 0 V entre 2 y 3.","12 V y 200 Ah entre 1 y 4; aproximadamente 12 V entre 2 y 3.","24 V y 200 Ah entre 1 y 4; aproximadamente 0 V entre 2 y 3."],"correct_index":1,"explanation":"El dibujo muestra dos baterías de 12 V/100 Ah en serie y un puente 2–3: 24 V nominales en extremos, 100 Ah en serie y 0 V a través del conductor ideal.","question_family":"GRAFICA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 337. El dibujo muestra dos baterías de 12 V/100 Ah en serie y un puente 2–3: 24 V nominales en extremos, 100 Ah en serie y 0 V a través del conductor ideal.","old_stem_md5":"d101bb6769ad3279cad26307006d7429","coverage_id":302080,"source_page":61,"old_family":"GRAFICA","old_validation_version":8,"kind":"grafica","externalKey":"T46-GRAF-04"},{"id":3148,"manual_page":"337","stem":"En el esquema recortado del examen, los bornes 2 y 3 están unidos y el arrancador se conecta únicamente a los extremos libres. ¿Qué orden de conexión y desconexión responde a la pregunta oficial reproducida?","options":["Conectar primero 3 y después 2; retirar primero 2 y después 3.","Conectar primero 2 y después 3; retirar primero 3 y después 2.","Conectar primero 1 y después 4; retirar primero 4 y después 1.","Conectar primero 4 y después 1; retirar primero 1 y después 4."],"correct_index":3,"explanation":"La pregunta 67 del modelo de examen aportado identifica como secuencia 4–1 para conectar y 1–4 para desconectar en el sistema de 24 V representado.","question_family":"GRAFICA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 337. La pregunta 67 del modelo de examen aportado identifica como secuencia 4–1 para conectar y 1–4 para desconectar en el sistema de 24 V representado.","old_stem_md5":"d7b0563637d3bd78129efda8517ead0e","coverage_id":302356,"source_page":61,"old_family":"GRAFICA","old_validation_version":8,"kind":"grafica","externalKey":"T46-GRAF-05"},{"id":3149,"manual_page":"329","stem":"En una intervención sobre una vía de doble sentido se dispone un equipo para iniciar la señalización desde la autobomba. Además de respetar los mínimos de distancia, ¿qué orden de despliegue y condición de visibilidad fija el CEIS?","options":["Señalizar simultáneamente ambos sentidos desde la víctima; disponer balizas visibles desde al menos 50 m.","Señalizar primero el carril ocupado y después el contrario; disponer balizas visibles desde al menos 50 m.","Señalizar primero el sentido contrario y después el ocupado; disponer balizas visibles desde al menos 100 m.","Señalizar primero el sentido del carril ocupado y después el contrario; disponer balizas visibles desde al menos 100 m."],"correct_index":3,"explanation":"En p. 329 se indica iniciar la señalización desde la bomba hacia el comienzo, primero en el sentido del carril ocupado y después en el contrario, con balizas visibles desde 100 m.","question_family":"2026_CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 329. En p. 329 se indica iniciar la señalización desde la bomba hacia el comienzo, primero en el sentido del carril ocupado y después en el contrario, con balizas visibles desde 100 m.","old_stem_md5":"4839013e0ba18e868cc4e94e09cd20f1","coverage_id":246205,"source_page":53,"old_family":"2026_CORRECTA","old_validation_version":8,"kind":"texto"},{"id":3150,"manual_page":"340","stem":"En un camión híbrido accidentado se ha accionado el desconectador HV delantero mientras el motor de combustión sigue en marcha. Según la descripción del CEIS, ¿cuál de las afirmaciones siguientes es INCORRECTA?","options":["Para alcanzar la ausencia de tensión HV, el texto exige también parar el motor de combustión interna.","El desconectador delantero asegura por sí solo la ausencia de tensión HV, aunque el motor térmico continúe funcionando.","Accionar el desconectador delantero no equivale necesariamente a dejar sin tensión el sistema HV.","El mando delantero de desconexión HV y el estado del motor térmico son comprobaciones diferenciadas."],"correct_index":1,"explanation":"El CEIS afirma que el desconectador delantero no produce por sí solo ausencia de tensión HV; es necesario parar también el motor térmico.","question_family":"2026_INCORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 340. El CEIS afirma que el desconectador delantero no produce por sí solo ausencia de tensión HV; es necesario parar también el motor térmico.","old_stem_md5":"fbefc98b3a560133fd3c157488ab9b9c","coverage_id":246206,"source_page":64,"old_family":"2026_INCORRECTA","old_validation_version":8,"kind":"texto"},{"id":3151,"manual_page":"351","stem":"Tras el vuelco de un autobús sobre un turismo se valoran la unión de ambos vehículos y una posible elevación. ¿Qué combinación refleja la estabilización solidaria y evita la maniobra expresamente desaconsejada?","options":["Estabilizar el autobús solamente y desplazar el turismo; izarlo por el techo con eslingas entre ventanillas.","Unirlos sin estabilizar primero y levantar el autobús; pasar las eslingas entre ventanillas enfrentadas.","Estabilizar ambos inicialmente y unirlos en bloque; no izar el autobús mediante eslingas entre ventanillas enfrentadas.","Separar los dos vehículos tras estabilizarlos y elevar el autobús; pasar las eslingas entre las ventanillas."],"correct_index":2,"explanation":"El manual describe primero estabilización individual y después solidaria con correas, además de prohibir izar el autobús por ventanas enfrentadas.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 351. El manual describe primero estabilización individual y después solidaria con correas, además de prohibir izar el autobús por ventanas enfrentadas.","old_stem_md5":"b3f20ac5e0936ff9302f7eb258ba9678","coverage_id":246207,"source_page":75,"old_family":"2026_RAZONAMIENTO","old_validation_version":8,"kind":"texto"},{"id":3152,"manual_page":"357","stem":"Se han protegido los ocupantes de un turismo y deben retirarse tanto un vidrio lateral templado como un parabrisas laminado. ¿Qué diferencia de preparación y eliminación coincide con las técnicas descritas?","options":["Templado: lámina adhesiva y granetazo en esquina; laminado: practicar abertura y cortar cerca del borde.","Templado: levantar marco y retirar completo; laminado: granetazo central y recogida de fragmentos sin corte.","Templado: corte periférico con sierra y sin lámina; laminado: granetazo en esquina con lámina adhesiva.","Templado: granetazo central antes de adherir lámina; laminado: perforarlo y retirarlo mediante ventosa."],"correct_index":0,"explanation":"La página 357 distingue vidrio templado con lámina y granetazo en esquina de parabrisas laminado con abertura y corte próximo al borde.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 357. La página 357 distingue vidrio templado con lámina y granetazo en esquina de parabrisas laminado con abertura y corte próximo al borde.","old_stem_md5":"b48cccddc5ca0e0cd4852a3e3a58211f","coverage_id":246208,"source_page":81,"old_family":"2026_RAZONAMIENTO","old_validation_version":8,"kind":"texto"},{"id":3153,"manual_page":"370","stem":"Durante la retirada de techo se prevé cortar los montantes B y C de un turismo con airbags de ventana. ¿Qué asociación entre inspección previa y zona de corte recoge el manual?","options":["Identificar el generador en el guardabarros anterior y cortar B en la base, sin dañar las bisagras.","Identificar el generador sobre C en el respaldo y cortar B a media altura, sin dañar las correas.","Identificar el generador en el marco del techo sobre B y cortar C lo más arriba posible, sin dañarlo.","Identificar el generador bajo el estribo de B y cortar C lo más abajo posible, sin dañarlo."],"correct_index":2,"explanation":"El CEIS señala verificar generadores de gas sobre el montante B en el marco del techo y extremar la precaución en los cortes de B y C.","question_family":"2026_CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 370. El CEIS señala verificar generadores de gas sobre el montante B en el marco del techo y extremar la precaución en los cortes de B y C.","old_stem_md5":"76c12ef350940f251e6abdfe4e565a8e","coverage_id":246210,"source_page":94,"old_family":"2026_CORRECTA","old_validation_version":8,"kind":"texto"},{"id":3154,"manual_page":"374","stem":"Se ejecuta un ataque combinado con un cilindro de separación que eleva parcialmente un vehículo y puntales instalados para sostenerlo. De acuerdo con la función de cada elemento, ¿qué afirmación es INCORRECTA?","options":["Los puntales deben ejercer también empuje ascendente para descargar el cilindro mientras continúa elevando.","El empuje vertical añadido por los puntales puede desalojar el cilindro de su punto de aplicación.","El cilindro aporta la fuerza de apertura, mientras los puntales mantienen la estabilidad conseguida.","Los puntales deben soportar el peso del vehículo sin aplicar una fuerza adicional hacia arriba."],"correct_index":0,"explanation":"El CEIS reserva a los puntales la sustentación y advierte de que su empuje ascendente podría hacer caer el cilindro.","question_family":"2026_INCORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 374. El CEIS reserva a los puntales la sustentación y advierte de que su empuje ascendente podría hacer caer el cilindro.","old_stem_md5":"b53c9193734463ec1e89ae7108e329c5","coverage_id":246211,"source_page":98,"old_family":"2026_INCORRECTA","old_validation_version":8,"kind":"texto"},{"id":3155,"manual_page":"383","stem":"Un camión volcado presenta las puertas deformadas, la trampilla superior eléctrica cerrada y el suministro ya desconectado. ¿Qué decisión compara correctamente dos vías de acceso descritas en el manual?","options":["La escotilla necesita apertura por medios alternativos; las puertas se prueban a mano o con palanqueta antes de usar hidráulica.","La escotilla se utiliza sin abrirse; las puertas se cortan sin intentar primero el accionamiento convencional.","La escotilla conserva apertura eléctrica; las puertas requieren directamente hidráulica antes de cualquier prueba manual.","La escotilla debe ignorarse siempre; las puertas deformadas se abren con hidráulica antes de probar una palanqueta."],"correct_index":0,"explanation":"En p. 383, una escotilla eléctrica cerrada sin alimentación requiere abrirse por otros medios; las puertas se comprueban primero manualmente.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 383. En p. 383, una escotilla eléctrica cerrada sin alimentación requiere abrirse por otros medios; las puertas se comprueban primero manualmente.","old_stem_md5":"0017ab8bb7d975ea71075834946f11ed","coverage_id":246197,"source_page":107,"old_family":"2026_RAZONAMIENTO","old_validation_version":8,"kind":"texto"},{"id":3156,"manual_page":"386","stem":"El primer cilindro de rescate ha desplazado el frontal de una cabina, pero su recorrido se ha agotado y limita el espacio para extraer a la víctima. ¿Qué disposición del segundo cilindro y posible retirada del primero explica el CEIS?","options":["Colocar el mayor por debajo del primero sin apoyos; retirar el inicial antes de cargar el segundo cilindro.","Colocar el mayor a la altura del primero sin asegurar extremos; retirar el inicial para iniciar el empuje.","Colocar el mayor apoyado solo en el techo del vehículo; retirar el inicial al alcanzar la cerradura.","Colocar el mayor por encima del primero con apoyos seguros; retirar el inicial solo cuando el segundo mantiene la apertura."],"correct_index":3,"explanation":"La página 386 sitúa el segundo cilindro por encima del primero, exige asegurar sus apoyos y prevé retirar el inicial si obstaculiza la extracción.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 386. La página 386 sitúa el segundo cilindro por encima del primero, exige asegurar sus apoyos y prevé retirar el inicial si obstaculiza la extracción.","old_stem_md5":"bee4d88256d8ff6c9d935eb1bf1142f5","coverage_id":246200,"source_page":110,"old_family":"2026_RAZONAMIENTO","old_validation_version":8,"kind":"texto"},{"id":3157,"manual_page":"328","stem":"El responsable de la intervención distingue el segundo y tercer momentos del procedimiento general representado. ¿Cuál es la asignación correcta si además hay que coordinar el emplazamiento con las fuerzas del orden?","options":["Segundo: estabilización de heridos y vehículo; tercero: reconocimiento de vehículo, heridos y entorno.","Segundo: estabilización exclusiva del entorno; tercero: reconocimiento de heridos y de vehículo.","Segundo: reconocimiento solo del vehículo; tercero: señalización y regulación de tráfico por bomberos.","Segundo: reconocimiento de heridos, vehículo y entorno; tercero: estabilización del vehículo y de heridos."],"correct_index":3,"explanation":"La imagen 100 distingue reconocimiento y estabilización, y el texto atribuye la regulación de circulación y accesos a fuerzas del orden.","question_family":"2026_CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 328. La imagen 100 distingue reconocimiento y estabilización, y el texto atribuye la regulación de circulación y accesos a fuerzas del orden.","old_stem_md5":"16d05e146b31cc96deea235f2bedb225","coverage_id":246204,"source_page":52,"old_family":"2026_CORRECTA","old_validation_version":8,"kind":"texto"},{"id":3158,"manual_page":"330","stem":"Durante una excarcelación se retira una puerta y varias piezas metálicas de la carrocería. La lona de herramientas está junto al perímetro interior y el equipo prepara el siguiente corte. ¿Qué destino de materiales es correcto?","options":["Mantener las herramientas sin uso junto a la víctima y trasladar los elementos cortados al borde de la caliente.","Guardar las herramientas sin uso en zona sucia y trasladar los elementos cortados a la zona limpia interior.","Guardar las herramientas sin uso en zona limpia y trasladar los elementos cortados a la zona sucia de la templada.","Trasladar herramientas sin uso y elementos cortados conjuntamente a la lona limpia del círculo interior."],"correct_index":2,"explanation":"El manual diferencia la zona limpia de herramientas en el límite interior de la zona sucia de fragmentos dentro de la zona templada.","question_family":"2026_CORRECTA","difficulty":"muy alta","proof":"CEIS Guadalajara, Rescate en accidentes de tráfico, p. 330. El manual diferencia la zona limpia de herramientas en el límite interior de la zona sucia de fragmentos dentro de la zona templada.","old_stem_md5":"a02d009d43cf02a5db6157b4b59e4401","coverage_id":246186,"source_page":54,"old_family":"2026_CORRECTA","old_validation_version":8,"kind":"texto"}]};
